def subtract(a, b):
    # Filter out empty intervals and collect all valid intervals
    a_intervals = [interval for interval in a if interval[0] < interval[1]]
    b_intervals = [interval for interval in b if interval[0] < interval[1]]

    # If a is empty, return empty list
    if not a_intervals:
        return []

    # If b is empty, merge and return a
    if not b_intervals:
        return merge_intervals(a_intervals)

    # Merge both sets of intervals
    a_merged = merge_intervals(a_intervals)
    b_merged = merge_intervals(b_intervals)

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current = a_start
        for b_start, b_end in b_merged:
            if b_end <= current:
                # b interval is completely before current position
                continue
            if b_start >= a_end:
                # b interval is completely after a interval
                break
            if b_start > current:
                # There's a gap before b interval
                result.append([current, b_start])
            current = max(current, b_end)

        if current < a_end:
            # Add remaining part of a interval
            result.append([current, a_end])

    return result

def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start, then by end
    sorted_intervals = sorted(intervals)
    merged = [sorted_intervals[0]]

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        if current_start <= last_end:
            # Overlapping or touching intervals - merge them
            merged[-1] = [last_start, max(last_end, current_end)]
        else:
            # Non-overlapping interval
            merged.append([current_start, current_end])

    return merged

